// Vendorovaný Unicode font pre PDF ponuku (#277). pdf-lib `StandardFonts` (WinAnsi/CP1252)
// NEvie zakódovať slovenské mäkčene (č/š/ž/ď/ť/ň/ľ/ô nie sú v CP1252), preto embedujeme
// vlastný TTF cez `@pdf-lib/fontkit`. Font = **DejaVu Sans** (public-domain-friendly
// Bitstream Vera derivát), PODMNOŽINA cez `pyftsubset` na rozsahy, ktoré PDF reálne
// používa (Basic Latin + Latin-1 + Latin Extended-A = celá slovenská abeceda + € + „" + ×).
//
// Prečo base64 v `.ts` (nie fs read/asset import): vždy sa zbundluje pod Vite SSR +
// adapter-node, žiadna runtime závislosť na súborovom systéme ani na layoute node_modules
// (rovnaká „bundling-safe" disciplína ako client-ip.ts/login-throttle.ts). Subset je malý
// (~32/27 KB), takže base64 v zdroji je akceptovateľné.
//
// Regenerácia: pyftsubset DejaVuSans[-Bold].ttf s rozsahmi (viď git história #277)
// --no-hinting --desubroutinize → base64 -w0 → sem. Licencia: DejaVu (Bitstream Vera).

export const DEJAVU_SANS_REGULAR_B64 =
	'';

export const DEJAVU_SANS_BOLD_B64 =
	'';
